	for _, q := range []string{"1 atan2 2", "metric atan2 2", "2 atan2 metric"} {
		e, err := parser.ParseExpr(q)
		if err != nil {
			t.Fatal(err)
		}
		qry, err := eng.NewInstantQuery(st, q, time.Unix(0, 0))
		if err != nil {
			t.Fatal(err)
		}
		res := qry.Exec(context.Background())
		if res.Err != nil {
			t.Fatal(res.Err)
		}
		t.Logf("%s => %v (%T)", q, res.Value, res.Value)
	}
